/**
 * Chainlink Functions JavaScript source code
 * This code runs off-chain to fetch API data and return it to the smart contract
 *
 * Expected args[0]: API URL to fetch data from
 * Returns: uint256 value from the API response
 */

// The URL is passed as the first argument
const apiUrl = args[0];

// Make the HTTP request
const apiResponse = await Functions.makeHttpRequest({
  url: apiUrl,
  method: "GET",
  headers: {
    "Content-Type": "application/json",
  },
});

// Check if the request was successful
if (apiResponse.error) {
  throw new Error(`API request failed: ${apiResponse.error}`);
}

// Extract the value from the response
// Adjust this path based on your API structure
// Example: for {"data": {"totalResults": 100}}, use apiResponse.data.data.totalResults
const value = apiResponse.data.totalResults;

if (typeof value !== "number") {
  throw new Error(`Invalid response: expected number, got ${typeof value}`);
}

// Return the value as bytes (encoded as uint256)
// The smart contract expects uint256
return Functions.encodeUint256(Math.floor(value));

